/**
 * Pure types of the signoff record: the five transitions a signature closes,
 * the principal a deployment names, the evidence pointers, and the one
 * `signoff/recorded` event a signed transition leaves in a session log.
 *
 * @module @deepseek-ai/dsh-signoff/types
 */

declare module '@deepseek-ai/dsh-session/types' {
  interface SessionEventMap {
    /**
     * One attributed human decision: which transition it closes, who the
     * deployment says signed it, the digest of the artefact signed, and the
     * pointers to what the signer had in view. Appended once per signature,
     * log-only and never part of a model request; a transition may be signed
     * again, and the newest record of a transition is the one consumers read.
     */
    'signoff/recorded': SignoffRecord
  }
}

/**
 * The five transitions that never complete without a signature: freezing a
 * spec, relaxing a security or compliance check, accepting a review, releasing
 * a deliverable, and releasing training data.
 */
export type SignoffTransition =
  | 'spec-freeze'
  | 'relaxation'
  | 'review-acceptance'
  | 'release'
  | 'training-data-release'

/**
 * Who signed, as the deployment's identity provider names them. This package
 * records a principal and never authenticates one, so `id` is only as
 * attributable as the provider that supplied it.
 */
export interface SignoffPrincipal {
  /** Only a person signs a transition; a rule that decides is not a signature. */
  readonly kind: 'human'
  /** Non-empty identity string from the deployment's identity provider. */
  readonly id: string
  /** Human-readable name for a reader of the log; non-empty when present. */
  readonly displayName?: string
}

/** One pointer to something the signer had in view when they signed. */
export interface SignoffEvidence {
  /** Non-empty kind of the referenced material, named by the recording caller. */
  readonly kind: string
  /** Non-empty reference the deployment can resolve: a path, a url, a session id, a digest. */
  readonly ref: string
}

/** Payload of `signoff/recorded`. */
export interface SignoffRecord {
  readonly transition: SignoffTransition
  readonly principal: SignoffPrincipal
  /** Lowercase 64-character SHA-256 hex of the artefact signed. */
  readonly artefactSha256: string
  /** What the signer had in view, bounded by the plugin's configured limits. */
  readonly evidence: readonly SignoffEvidence[]
}

/**
 * Signoffs: the attributable human gate of the governance rollout. One
 * `signoff/recorded` event per signed transition names the principal the
 * deployment's identity provider supplied, the digest of the artefact signed,
 * and the pointers to what the signer had in view; the session log is the whole
 * record, and folding it is how a consumer learns whether a transition was
 * signed. Nothing here authenticates a principal and nothing reaches a model
 * request. The
 * [attributable-decisions Agent Note](../../../.agents/notes/proposed/architecture/2026-09-06-attributable-decisions.md)
 * owns the design rationale.
 * @module @deepseek-ai/dsh-signoff
 */

import { Context, Service } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { HarnessError } from '@deepseek-ai/dsh-llm'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import type { SignoffEvidence, SignoffPrincipal, SignoffRecord, SignoffTransition } from './types.ts'

export type * from './types.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    signoffs: SignoffService
  }
}

/** Every {@link SignoffTransition}, for validation and for option advertisement. */
export const SIGNOFF_TRANSITIONS: readonly SignoffTransition[] = [
  'spec-freeze',
  'relaxation',
  'review-acceptance',
  'release',
  'training-data-release',
]

/** Digest form every `artefactSha256` must take: lowercase SHA-256 hex. */
export const ARTEFACT_SHA256 = /^[0-9a-f]{64}$/

/** Stable error code of a record this service refuses to append. */
export type SignoffErrorCode = 'SIGNOFF_INVALID_RECORD'

/** Error returned when a record cannot become a durable signature. */
export class SignoffError extends HarnessError {
  /**
   * @param message - human-readable reason, naming the field at fault.
   * @param code - stable machine-routable classification.
   */
  // Keep the constructor to narrow HarnessError's string code at this boundary.
  // oxlint-disable-next-line typescript/no-useless-constructor -- type-only narrowing
  constructor(message: string, code: SignoffErrorCode) {
    super(message, code)
  }
}

/** What one caller states about a signature; the service validates it before it becomes durable. */
export interface SignoffInput {
  readonly transition: SignoffTransition
  readonly principal: SignoffPrincipal
  /** Lowercase 64-character SHA-256 hex of the artefact signed. */
  readonly artefactSha256: string
  /** Pointers to what the signer had in view; empty is a valid, less useful record. */
  readonly evidence: readonly SignoffEvidence[]
}

/** Deployment bounds on one durable record, validated from `cordis.yml`. */
export interface Config {
  /** Positive maximum number of evidence pointers one record may carry. */
  maxEvidence: number
  /** Positive maximum length in characters of one evidence `kind` or `ref`. */
  maxEvidenceRefChars: number
}

/**
 * The newest record of one transition in a log, or `undefined` when the log
 * holds none. The pure fold: a consumer holding persisted events needs no
 * service, and a resumed session needs no catch-up because replaying the log IS
 * the state.
 * @param events - session events in log order; other event types are skipped.
 * @param transition - the transition whose newest signature is wanted.
 * @returns the last matching record, or `undefined` without one.
 */
export function latestSignoff(
  events: readonly SessionEvent[],
  transition: SignoffTransition,
): SignoffRecord | undefined {
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index] as SessionEvent
    if (event.type === 'signoff/recorded' && event.data.transition === transition) return event.data
  }
  return undefined
}

/** Signoffs (`ctx.signoffs`): attributed human decisions recorded in the session log. */
export class SignoffService extends Service {
  static Config: z<Config> = z.object({
    maxEvidence: z.natural().min(1).required(),
    maxEvidenceRefChars: z.natural().min(1).required(),
  })

  private readonly config: Config

  constructor(ctx: Context, config: Config) {
    super(ctx, 'signoffs')
    this.config = config
  }

  /**
   * Record one signature on the agent's session and return the detached record.
   * The record is validated before anything is appended, so a session log never
   * carries a signature this service refused.
   * @param agent - the agent whose session carries the transition being signed.
   * @param input - the transition, principal, artefact digest, and evidence.
   * @returns the record exactly as it was appended.
   * @throws {@link SignoffError} when a field cannot become a durable signature,
   *   or when the same session already signed this transition on another artefact.
   */
  record(agent: Agent, input: SignoffInput): SignoffRecord {
    const record = this.validate(input)
    const standing = latestSignoff(agent.session.events, record.transition)
    if (standing !== undefined && standing.artefactSha256 !== record.artefactSha256) {
      throw new SignoffError(
        `this session signed "${record.transition}" on artefact ${standing.artefactSha256}, which ${record.artefactSha256} does not match`,
        'SIGNOFF_INVALID_RECORD',
      )
    }
    agent.session.append('signoff/recorded', record)
    return record
  }

  /**
   * The newest signature of one transition on the agent's own session.
   * @param agent - the agent whose session log is folded.
   * @param transition - the transition whose newest signature is wanted.
   * @returns the last matching record, or `undefined` without one.
   */
  latest(agent: Agent, transition: SignoffTransition): SignoffRecord | undefined {
    return latestSignoff(agent.session.events, transition)
  }

  /** Reject every field a durable record may not carry, then freeze the record. */
  private validate(input: SignoffInput): SignoffRecord {
    if (!SIGNOFF_TRANSITIONS.includes(input.transition)) {
      throw new SignoffError(`transition ${JSON.stringify(input.transition)} is not one of ${SIGNOFF_TRANSITIONS.join(', ')}`, 'SIGNOFF_INVALID_RECORD')
    }
    if (!ARTEFACT_SHA256.test(input.artefactSha256)) {
      throw new SignoffError(`artefactSha256 ${JSON.stringify(input.artefactSha256)} is not a lowercase 64-character SHA-256 hex digest`, 'SIGNOFF_INVALID_RECORD')
    }
    const { principal } = input
    if (principal.kind !== 'human') {
      throw new SignoffError(`principal kind ${JSON.stringify(principal.kind)} is not "human"; only a person signs a transition`, 'SIGNOFF_INVALID_RECORD')
    }
    if (principal.id.length === 0) throw new SignoffError('principal id is empty, so the record names nobody', 'SIGNOFF_INVALID_RECORD')
    if (principal.displayName !== undefined && principal.displayName.length === 0) {
      throw new SignoffError('principal displayName is present and empty; omit it instead', 'SIGNOFF_INVALID_RECORD')
    }
    if (input.evidence.length > this.config.maxEvidence) {
      throw new SignoffError(`the record carries ${String(input.evidence.length)} evidence pointers, above the configured maximum of ${String(this.config.maxEvidence)}`, 'SIGNOFF_INVALID_RECORD')
    }
    for (const evidence of input.evidence) this.validateEvidence(evidence)
    return {
      transition: input.transition,
      principal: {
        kind: principal.kind,
        id: principal.id,
        ...principal.displayName === undefined ? {} : { displayName: principal.displayName },
      },
      artefactSha256: input.artefactSha256,
      evidence: input.evidence.map(evidence => ({ kind: evidence.kind, ref: evidence.ref })),
    }
  }

  /** Reject one evidence pointer that names nothing or exceeds the configured length. */
  private validateEvidence(evidence: SignoffEvidence): void {
    for (const [field, value] of [['kind', evidence.kind], ['ref', evidence.ref]] as const) {
      if (value.length === 0) throw new SignoffError(`evidence ${field} is empty, so the pointer names nothing`, 'SIGNOFF_INVALID_RECORD')
      if (value.length > this.config.maxEvidenceRefChars) {
        throw new SignoffError(`evidence ${field} is ${String(value.length)} characters, above the configured maximum of ${String(this.config.maxEvidenceRefChars)}`, 'SIGNOFF_INVALID_RECORD')
      }
    }
  }
}

export default SignoffService

/**
 * Package-owned invariant over the one durable record this package writes.
 *
 * A `signoff/recorded` states a transition from the closed set, a principal a
 * reader can address, a lowercase SHA-256 digest of what was signed, and
 * evidence pointers that name something. The relation the log owns is artefact
 * stability: a session that signs one transition twice signs the same artefact
 * both times, because a second signature under a different digest would let a
 * reader of either record believe the other transition was signed on its own
 * artefact.
 *
 * What the log cannot show, and this companion therefore never claims: that the
 * principal is the person named, that the digest addresses a real artefact,
 * that the evidence refs resolve, or that the signer saw them.
 *
 * @module @deepseek-ai/dsh-signoff/invariant
 */

import type { Context } from '@deepseek-ai/cordis'
import { sessionEventValidator } from '@deepseek-ai/dsh-invariants'
import type { InvariantFailure, InvariantInstaller } from '@deepseek-ai/dsh-invariants'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import { ARTEFACT_SHA256, latestSignoff, SIGNOFF_TRANSITIONS } from './index.ts'
import type { SignoffRecord } from './types.ts'

const PACKAGE_NAME = '@deepseek-ai/dsh-signoff'

/** Cordis companion plugin name. */
export const name = 'signoff-invariant'
/** Service required before the companion can reserve package ownership. */
export const inject = ['invariants']

/** Report every field of one record a durable signature may not carry. */
function checkFields(record: SignoffRecord, fail: InvariantFailure): void {
  if (!SIGNOFF_TRANSITIONS.includes(record.transition)) {
    fail(`signoff/recorded carries unknown transition ${JSON.stringify(record.transition)}`)
  }
  if (!ARTEFACT_SHA256.test(record.artefactSha256)) {
    fail(`signoff/recorded carries artefactSha256 ${JSON.stringify(record.artefactSha256)}, which is not a lowercase 64-character SHA-256 hex digest`)
  }
  const { principal } = record
  if (principal.kind !== 'human') fail(`signoff/recorded carries principal kind ${JSON.stringify(principal.kind)} rather than "human"`)
  if (principal.id.length === 0) fail('signoff/recorded carries an empty principal id, so it names nobody')
  if (principal.displayName !== undefined && principal.displayName.length === 0) {
    fail('signoff/recorded carries an empty principal displayName')
  }
  for (const evidence of record.evidence) {
    if (evidence.kind.length === 0) fail('signoff/recorded carries an evidence pointer with an empty kind')
    if (evidence.ref.length === 0) fail('signoff/recorded carries an evidence pointer with an empty ref')
  }
}

/**
 * Report one recorded signature that breaks a field rule or the artefact
 * stability of its own session.
 * @param prior - the session's committed events, oldest first.
 * @param event - the candidate session event.
 * @param fail - the reporter for a broken relation.
 */
export function checkSignoffEvent(prior: readonly SessionEvent[], event: SessionEvent, fail: InvariantFailure): void {
  if (event.type !== 'signoff/recorded') return
  const record = event.data
  checkFields(record, fail)
  const standing = latestSignoff(prior, record.transition)
  if (standing !== undefined && standing.artefactSha256 !== record.artefactSha256) {
    fail(`signoff/recorded signs "${record.transition}" on artefact ${record.artefactSha256}, which this session already signed on ${standing.artefactSha256}`)
  }
}

/** Check existing sessions and every candidate event before Session publishes it. */
const install: InvariantInstaller = sessionEventValidator(checkSignoffEvent, ctx => ctx.sessions.list())

/**
 * Register the signoff-record invariant companion.
 * @param ctx - Cordis context carrying the invariant service.
 * @returns the installed registration's disposer after setup succeeds.
 */
export const apply = (ctx: Context): Promise<() => void> =>
  Promise.resolve(ctx.invariants.register(PACKAGE_NAME, install))

